import { Popover } from "@base-ui/react/popover";

import { CalendarPanel } from "./calendar-panel";
import { useControlled } from "./hooks";
import { formatClock, formatDay, hourCycleFor, type HourCycle } from "./time";
import { TimePanel } from "./time-panel";
import { cn } from "./utils";

export type DateTimePickerProps = {
  value?: Date | null;
  defaultValue?: Date | null;
  onChange?: (date: Date | null) => void;
  /** Which parts are editable — `UIDatePicker.Mode`. */
  mode?: "date" | "time" | "dateTime";
  /** Pills that open popovers (`.compact`), or the panels laid out in place (`.inline`). */
  display?: "compact" | "inline";
  locale?: string;
  hourCycle?: HourCycle;
  minuteInterval?: number;
  min?: Date;
  max?: Date;
  disabled?: boolean;
  className?: string;
  /** Placeholder labels when there is no value. */
  labels?: { date?: string; time?: string };
};

/** The compact pill and its popover, for composing your own rows. */
export const pillClass =
  "inline-flex h-[34px] items-center rounded-lg bg-[var(--cdp-fill)] px-3 text-[17px] leading-none text-[var(--cdp-label)] transition-[background-color,color] outline-none hover:bg-[var(--cdp-fill-hover)] focus-visible:ring-2 focus-visible:ring-[var(--cdp-tint)] active:opacity-60 disabled:opacity-40 data-popup-open:text-[var(--cdp-tint)]";

export const popupClass =
  "cdp origin-(--transform-origin) rounded-[13px] bg-[var(--cdp-bg)] shadow-[var(--cdp-shadow)] outline-none data-open:animate-[cdp-pop-in_260ms_cubic-bezier(0.18,0.9,0.32,1.15)] data-closed:animate-[cdp-pop-out_140ms_ease-in]";

/**
 * The iOS 14+ date picker for the web. Compact display shows the date and
 * time as pills; each opens a popover — the calendar or the time panel —
 * anchored to it. Inline display lays the panels out in place.
 */
export function DateTimePicker({
  value: valueProp,
  defaultValue = null,
  onChange,
  mode = "dateTime",
  display = "compact",
  locale = navigator.language,
  hourCycle: hourCycleProp,
  minuteInterval = 1,
  min,
  max,
  disabled = false,
  className,
  labels,
}: DateTimePickerProps) {
  const [value, setValue] = useControlled(valueProp, defaultValue, onChange);
  const hourCycle = hourCycleProp ?? hourCycleFor(locale);
  const showDate = mode !== "time";
  const showTime = mode !== "date";
  // Panels always have something to edit; a picked day or time starts from now.
  const draft = value ?? new Date();

  const calendar = (
    <CalendarPanel value={value} onChange={setValue} locale={locale} min={min} max={max} />
  );
  const time = (
    <TimePanel
      value={draft}
      onChange={setValue}
      locale={locale}
      hourCycle={hourCycle}
      minuteInterval={minuteInterval}
    />
  );

  const timePopover = (
    <Popover.Root>
      <Popover.Trigger className={pillClass} disabled={disabled} data-slot="time-trigger">
        {value ? formatClock(value, locale, hourCycle) : (labels?.time ?? "Time")}
      </Popover.Trigger>
      <Popover.Portal>
        <Popover.Positioner sideOffset={8} align="center" className="isolate z-50">
          <Popover.Popup className={popupClass} data-slot="time-popup">
            {time}
          </Popover.Popup>
        </Popover.Positioner>
      </Popover.Portal>
    </Popover.Root>
  );

  if (display === "inline") {
    return (
      <div
        className={cn(
          "cdp inline-flex flex-col items-stretch rounded-[13px] bg-[var(--cdp-bg)]",
          className,
        )}
        data-slot="date-time-picker"
        data-display="inline"
      >
        {showDate && calendar}
        {/* As on iOS: the time sits on a "Time" row under the calendar and opens the wheels. */}
        {showTime &&
          (showDate ? (
            <div className="mx-3 flex h-[52px] items-center justify-between border-t border-[var(--cdp-fill)]">
              <span className="text-[17px] text-[var(--cdp-label)]">{labels?.time ?? "Time"}</span>
              {timePopover}
            </div>
          ) : (
            time
          ))}
      </div>
    );
  }

  return (
    <div
      className={cn("cdp inline-flex items-center gap-2", className)}
      data-slot="date-time-picker"
      data-display="compact"
    >
      {showDate && (
        <Popover.Root>
          <Popover.Trigger className={pillClass} disabled={disabled} data-slot="date-trigger">
            {value ? formatDay(value, locale) : (labels?.date ?? "Date")}
          </Popover.Trigger>
          <Popover.Portal>
            <Popover.Positioner sideOffset={8} align="center" className="isolate z-50">
              <Popover.Popup className={popupClass} data-slot="date-popup">
                {calendar}
              </Popover.Popup>
            </Popover.Positioner>
          </Popover.Portal>
        </Popover.Root>
      )}
      {showTime && timePopover}
    </div>
  );
}

import * as React from "react";

import {
  addDays,
  addMonths,
  isDayDisabled,
  isSameDay,
  monthDiff,
  monthGrid,
  shiftMonth,
  startOfDay,
  weekStartFor,
  withDay,
  yearMonthOf,
  type YearMonth,
} from "./calendar";
import { formatFullDate, formatMonthYear, monthNames, weekdayNames } from "./time";
import { cn } from "./utils";
import { Wheel, WheelHighlight } from "./wheel";

export type CalendarPanelLabels = {
  previousMonth: string;
  nextMonth: string;
  month: string;
  year: string;
};

export const CALENDAR_LABELS: CalendarPanelLabels = {
  previousMonth: "Previous month",
  nextMonth: "Next month",
  month: "Month",
  year: "Year",
};

export type CalendarPanelProps = {
  value: Date | null;
  onChange: (date: Date) => void;
  locale?: string;
  min?: Date;
  max?: Date;
  /** Accessible names; visible text comes from `Intl`. */
  labels?: Partial<CalendarPanelLabels>;
  /** Injected for tests and stories. */
  today?: Date;
  className?: string;
};

const YEAR_SPAN = 100;
const SWIPE_PX = 40;

function Chevron({ className }: { className?: string }) {
  return (
    <svg viewBox="0 0 20 20" className={cn("size-5", className)} aria-hidden fill="none">
      <path
        d="M7.5 4.5 13 10l-5.5 5.5"
        stroke="currentColor"
        strokeWidth="2.25"
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </svg>
  );
}

/**
 * The iOS inline calendar: month title that opens month/year wheels, next
 * and previous month, a grid of circles. Months slide, the wheels cross-fade
 * in over the grid, a horizontal swipe changes month, and the keyboard walks
 * the grid (arrows, Home/End, PageUp/PageDown, Enter).
 */
export function CalendarPanel({
  value,
  onChange,
  locale = navigator.language,
  min,
  max,
  labels: labelsProp,
  today: todayProp,
  className,
}: CalendarPanelProps) {
  const labels = { ...CALENDAR_LABELS, ...labelsProp };
  const today = todayProp ?? startOfDay(new Date());
  const weekStart = weekStartFor(locale);
  const [view, setView] = React.useState<YearMonth>(() => yearMonthOf(value ?? today));
  const [dir, setDir] = React.useState<-1 | 0 | 1>(0);
  const [picking, setPicking] = React.useState(false);
  const [focusDate, setFocusDate] = React.useState<Date>(value ?? today);
  const wantFocus = React.useRef(false);
  const grid = React.useRef<HTMLDivElement>(null);
  const swipe = React.useRef<{ x: number; y: number } | null>(null);

  // A value set from outside moves the view to its month.
  const [seen, setSeen] = React.useState(value);
  if (value !== seen) {
    setSeen(value);
    if (value && monthDiff(view, yearMonthOf(value)) !== 0) {
      setDir(0);
      setView(yearMonthOf(value));
      setFocusDate(value);
    }
  }

  const show = (next: YearMonth, direction: -1 | 0 | 1) => {
    setDir(direction);
    setView(next);
  };
  const shift = (by: number) => show(shiftMonth(view, by), by > 0 ? 1 : -1);

  const canShift = (by: number) => {
    const target = shiftMonth(view, by);
    if (by < 0 && min && monthDiff(yearMonthOf(min), target) < 0) return false;
    if (by > 0 && max && monthDiff(target, yearMonthOf(max)) < 0) return false;
    return true;
  };

  const pick = (date: Date) => {
    setFocusDate(date);
    onChange(withDay(value ?? today, date.getFullYear(), date.getMonth(), date.getDate()));
  };

  const moveFocus = (next: Date) => {
    if (isDayDisabled(next, min, max)) return;
    wantFocus.current = true;
    setFocusDate(next);
    const diff = monthDiff(view, yearMonthOf(next));
    if (diff !== 0) show(yearMonthOf(next), diff > 0 ? 1 : -1);
  };

  React.useEffect(() => {
    if (!wantFocus.current) return;
    wantFocus.current = false;
    grid.current
      ?.querySelector<HTMLButtonElement>(`[data-date="${startOfDay(focusDate).getTime()}"]`)
      ?.focus();
  }, [focusDate]);

  const onGridKeyDown = (e: React.KeyboardEvent) => {
    const f = focusDate;
    const jump = new Map<string, () => Date>([
      ["ArrowLeft", () => addDays(f, -1)],
      ["ArrowRight", () => addDays(f, 1)],
      ["ArrowUp", () => addDays(f, -7)],
      ["ArrowDown", () => addDays(f, 7)],
      ["Home", () => addDays(f, -((f.getDay() - weekStart + 7) % 7))],
      ["End", () => addDays(f, 6 - ((f.getDay() - weekStart + 7) % 7))],
      ["PageUp", () => addMonths(f, e.shiftKey ? -12 : -1)],
      ["PageDown", () => addMonths(f, e.shiftKey ? 12 : 1)],
    ]);
    const to = jump.get(e.key);
    if (!to) return;
    e.preventDefault();
    moveFocus(to());
  };

  const onPointerDown = (e: React.PointerEvent) => {
    if (e.pointerType === "mouse") return;
    swipe.current = { x: e.clientX, y: e.clientY };
  };
  const onPointerUp = (e: React.PointerEvent) => {
    const s = swipe.current;
    swipe.current = null;
    if (!s) return;
    const dx = e.clientX - s.x;
    if (Math.abs(dx) < SWIPE_PX || Math.abs(dx) < Math.abs(e.clientY - s.y)) return;
    const by = dx < 0 ? 1 : -1;
    if (canShift(by)) shift(by);
  };

  const rows = monthGrid(view.year, view.month, weekStart);
  const viewDate = new Date(view.year, view.month, 1);
  const months = monthNames(locale).map((label, month) => ({ value: month, label }));
  const years = Array.from({ length: YEAR_SPAN * 2 + 1 }, (_, i) => {
    const year = today.getFullYear() - YEAR_SPAN + i;
    return { value: year, label: String(year) };
  });

  return (
    <div className={cn("cdp flex w-[312px] flex-col select-none", className)} data-slot="calendar">
      <div className="flex h-11 items-center justify-between pr-1 pl-2.5">
        <button
          type="button"
          aria-expanded={picking}
          onClick={() => setPicking((p) => !p)}
          className="flex h-9 items-center gap-1 rounded-lg px-1.5 text-[17px] font-semibold tracking-[-0.01em] text-[var(--cdp-label)] transition-opacity outline-none active:opacity-50 focus-visible:ring-2 focus-visible:ring-[var(--cdp-tint)]"
        >
          <span>{formatMonthYear(viewDate, locale)}</span>
          <Chevron
            className={cn(
              "size-4 text-[var(--cdp-tint)] transition-transform duration-200",
              picking && "rotate-90",
            )}
          />
        </button>
        <div
          className={cn(
            "flex items-center transition-opacity duration-150",
            picking && "pointer-events-none opacity-0",
          )}
        >
          <button
            type="button"
            aria-label={labels.previousMonth}
            disabled={!canShift(-1)}
            onClick={() => shift(-1)}
            className="flex size-11 items-center justify-center rounded-full text-[var(--cdp-tint)] transition-opacity outline-none active:opacity-40 disabled:opacity-30 focus-visible:ring-2 focus-visible:ring-[var(--cdp-tint)]"
          >
            <Chevron className="rotate-180" />
          </button>
          <button
            type="button"
            aria-label={labels.nextMonth}
            disabled={!canShift(1)}
            onClick={() => shift(1)}
            className="flex size-11 items-center justify-center rounded-full text-[var(--cdp-tint)] transition-opacity outline-none active:opacity-40 disabled:opacity-30 focus-visible:ring-2 focus-visible:ring-[var(--cdp-tint)]"
          >
            <Chevron />
          </button>
        </div>
      </div>

      <div className="relative grid px-1.5 pb-1.5">
        {/* Day grid and the month/year wheels share the cell; one fades out as the other fades in. */}
        <div
          className={cn(
            "col-start-1 row-start-1 transition-[opacity,transform] duration-200",
            picking && "pointer-events-none scale-95 opacity-0",
          )}
          aria-hidden={picking}
        >
          <div className="grid grid-cols-7" aria-hidden>
            {weekdayNames(locale, weekStart).map((name, i) => (
              <div
                key={i}
                className="flex h-8 items-center justify-center text-[13px] font-semibold text-[var(--cdp-tertiary)]"
              >
                {name}
              </div>
            ))}
          </div>
          <div
            ref={grid}
            role="grid"
            tabIndex={-1}
            aria-label={formatMonthYear(viewDate, locale)}
            key={`${view.year}-${view.month}`}
            data-dir={dir}
            onKeyDown={onGridKeyDown}
            onPointerDown={onPointerDown}
            onPointerUp={onPointerUp}
            className="grid grid-cols-7 gap-y-0.5 data-[dir=-1]:animate-[cdp-slide-from-left_240ms_cubic-bezier(0.2,0.9,0.3,1)] data-[dir=1]:animate-[cdp-slide-from-right_240ms_cubic-bezier(0.2,0.9,0.3,1)]"
            style={{ touchAction: "pan-y" }}
          >
            {rows.flat().map(({ date, inMonth }, i) => {
              if (!inMonth) return <div key={i} role="gridcell" aria-hidden />;
              const selected = isSameDay(date, value);
              const isToday = isSameDay(date, today);
              const disabled = isDayDisabled(date, min, max);
              return (
                <button
                  key={i}
                  type="button"
                  role="gridcell"
                  aria-selected={selected}
                  aria-label={formatFullDate(date, locale)}
                  aria-current={isToday ? "date" : undefined}
                  data-date={startOfDay(date).getTime()}
                  data-today={isToday || undefined}
                  data-selected={selected || undefined}
                  tabIndex={isSameDay(date, focusDate) ? 0 : -1}
                  disabled={disabled}
                  onClick={() => pick(date)}
                  onFocus={() => setFocusDate(date)}
                  className={cn(
                    "mx-auto flex size-10 items-center justify-center rounded-full text-[20px] leading-none tabular-nums transition-transform duration-150 outline-none active:scale-90 focus-visible:ring-2 focus-visible:ring-[var(--cdp-tint)] focus-visible:ring-offset-2 focus-visible:ring-offset-[var(--cdp-bg)] disabled:opacity-30",
                    selected
                      ? isToday
                        ? "bg-[var(--cdp-tint)] font-semibold text-[var(--cdp-on-tint)]"
                        : "bg-[var(--cdp-tint-fill)] font-semibold text-[var(--cdp-tint)]"
                      : isToday
                        ? "text-[var(--cdp-tint)] hover:bg-[var(--cdp-fill)]"
                        : "text-[var(--cdp-label)] hover:bg-[var(--cdp-fill)]",
                  )}
                >
                  {date.getDate()}
                </button>
              );
            })}
          </div>
        </div>

        <div
          className={cn(
            "cdp-wheel-mask relative col-start-1 row-start-1 flex items-center justify-center gap-2 px-2 transition-[opacity,transform] duration-200",
            !picking && "pointer-events-none scale-95 opacity-0",
          )}
          aria-hidden={!picking}
          data-slot="month-year"
        >
          <WheelHighlight className="inset-x-2" />
          <Wheel
            aria-label={labels.month}
            options={months}
            value={view.month}
            loop
            visibleRows={7}
            onChange={(month) => show({ year: view.year, month }, 0)}
            className="w-40"
          />
          <Wheel
            aria-label={labels.year}
            options={years}
            value={view.year}
            visibleRows={7}
            onChange={(year) => show({ year, month: view.month }, 0)}
            className="w-24"
          />
        </div>
      </div>
    </div>
  );
}

import * as React from "react";

import { withTime } from "./calendar";
import { SegmentedControl } from "./segmented-control";
import { stepValue, typeDigit } from "./segments";
import { dayPeriodLabels, hourCycleFor, to12, to24, type HourCycle } from "./time";
import { cn, pad2 } from "./utils";
import { Wheel, WheelHighlight } from "./wheel";

export type TimePanelLabels = {
  time: string;
  hour: string;
  minute: string;
  dayPeriod: string;
};

export const TIME_LABELS: TimePanelLabels = {
  time: "Time",
  hour: "Hour",
  minute: "Minute",
  dayPeriod: "Day period",
};

export type TimePanelProps = {
  value: Date;
  onChange: (date: Date) => void;
  locale?: string;
  hourCycle?: HourCycle;
  /** Accessible names; visible text comes from `Intl`. */
  labels?: Partial<TimePanelLabels>;
  /** Minute wheel granularity, like `UIDatePicker.minuteInterval`. */
  minuteInterval?: number;
  /** Hide the wheels and keep only the typed field. */
  wheels?: boolean;
  className?: string;
};

type Segment = "hour" | "minute";

/**
 * Time entry the way iOS 14+ does it, both halves at once: a field of
 * segments that takes digits from a keyboard or keypad and steps with the
 * arrows, and the hour / minute / period wheels underneath. Either side
 * moves the other — type "930" and the wheels spin there; fling a wheel and
 * the digits follow.
 */
export function TimePanel({
  value,
  onChange,
  locale = navigator.language,
  hourCycle: hourCycleProp,
  minuteInterval = 1,
  wheels = true,
  labels: labelsProp,
  className,
}: TimePanelProps) {
  const labels = { ...TIME_LABELS, ...labelsProp };
  const hourCycle = hourCycleProp ?? hourCycleFor(locale);
  const twelve = hourCycle === "h12";
  const hours24 = value.getHours();
  const minutes = value.getMinutes();
  const { hour: hour12, pm } = to12(hours24);
  const hourShown = twelve ? hour12 : hours24;
  const hourMin = twelve ? 1 : 0;
  const hourMax = twelve ? 12 : 23;
  const periods = dayPeriodLabels(locale);

  const [typing, setTyping] = React.useState<{ segment: Segment; buffer: string } | null>(null);
  const hourRef = React.useRef<HTMLInputElement>(null);
  const minuteRef = React.useRef<HTMLInputElement>(null);

  const setHour = (shown: number) =>
    onChange(withTime(value, twelve ? to24(shown, pm) : shown, minutes));
  const setMinute = (m: number) => onChange(withTime(value, hours24, m));
  const setPm = (next: boolean) => onChange(withTime(value, to24(hour12, next), minutes));

  const focusSegment = (segment: Segment) => {
    const el = segment === "hour" ? hourRef.current : minuteRef.current;
    el?.focus();
    el?.select();
  };

  const typeInto = (segment: Segment, digit: string) => {
    const buffer = typing?.segment === segment ? typing.buffer : "";
    const step =
      segment === "hour"
        ? typeDigit(buffer, digit, hourMin, hourMax)
        : typeDigit(buffer, digit, 0, 59);
    if (step.value !== null) (segment === "hour" ? setHour : setMinute)(step.value);
    if (step.done) {
      setTyping(null);
      if (segment === "hour") focusSegment("minute");
    } else {
      setTyping({ segment, buffer: step.buffer });
    }
  };

  const onSegmentKeyDown = (segment: Segment) => (e: React.KeyboardEvent<HTMLInputElement>) => {
    const key = e.key;
    if (/^\d$/.test(key)) {
      e.preventDefault();
      typeInto(segment, key);
      return;
    }
    const by = key === "ArrowUp" ? 1 : key === "ArrowDown" ? -1 : 0;
    if (by) {
      e.preventDefault();
      setTyping(null);
      if (segment === "hour") setHour(stepValue(hourShown, by, hourMin, hourMax));
      else setMinute(stepValue(minutes, by * minuteInterval, 0, 59));
      return;
    }
    if (key === "ArrowLeft" && segment === "minute") {
      e.preventDefault();
      focusSegment("hour");
    } else if (key === "ArrowRight" && segment === "hour") {
      e.preventDefault();
      focusSegment("minute");
    } else if (key === "Backspace" || key === "Delete") {
      e.preventDefault();
      setTyping({ segment, buffer: "" });
    } else if (twelve && (key === "a" || key === "A" || key === "p" || key === "P")) {
      e.preventDefault();
      setPm(key === "p" || key === "P");
    } else if (key === "Enter") {
      e.currentTarget.blur();
    } else if (key.length === 1 && !e.metaKey && !e.ctrlKey) {
      e.preventDefault();
    }
  };

  // Mobile keypads and IMEs insert text without a key name; `beforeinput`
  // carries the digit either way.
  const onBeforeInput = (segment: Segment) => (e: React.FormEvent<HTMLInputElement>) => {
    e.preventDefault();
    const data = (e.nativeEvent as InputEvent).data ?? "";
    for (const ch of data) if (/\d/.test(ch)) typeInto(segment, ch);
  };

  // An engine that skipped `beforeinput` still changes the input: whatever
  // was added to the shown text is what was typed.
  const onInput = (segment: Segment) => (e: React.ChangeEvent<HTMLInputElement>) => {
    const added = e.target.value.replace(shownText(segment), "");
    for (const ch of added) if (/\d/.test(ch)) typeInto(segment, ch);
  };

  const shownText = (segment: Segment) => {
    if (typing?.segment === segment) return typing.buffer;
    if (segment === "hour") return twelve ? String(hourShown) : pad2(hourShown);
    return pad2(minutes);
  };

  const segmentClass =
    "box-content h-10 rounded-md bg-transparent px-1 text-center text-[32px] leading-none font-light tabular-nums text-[var(--cdp-label)] caret-transparent outline-none selection:bg-transparent focus:bg-[var(--cdp-tint-fill)] focus:text-[var(--cdp-tint)]";

  const hourOptions = Array.from({ length: hourMax - hourMin + 1 }, (_, i) => {
    const h = hourMin + i;
    return { value: h, label: twelve ? String(h) : pad2(h) };
  });
  const minuteOptions = Array.from({ length: Math.ceil(60 / minuteInterval) }, (_, i) => ({
    value: i * minuteInterval,
    label: pad2(i * minuteInterval),
  }));

  return (
    <div
      className={cn("cdp flex w-[280px] flex-col gap-2 p-3 select-none", className)}
      data-slot="time"
    >
      <div className="flex items-center justify-between gap-3">
        <div
          role="group"
          aria-label={labels.time}
          className="flex h-11 items-center rounded-lg bg-[var(--cdp-fill)] px-1.5"
          data-slot="time-field"
        >
          <input
            ref={hourRef}
            aria-label={labels.hour}
            inputMode="numeric"
            autoComplete="off"
            value={shownText("hour")}
            onChange={onInput("hour")}
            onBeforeInput={onBeforeInput("hour")}
            onKeyDown={onSegmentKeyDown("hour")}
            onFocus={(e) => e.currentTarget.select()}
            onBlur={() => setTyping(null)}
            className={segmentClass}
            style={{ width: `${Math.max(1, shownText("hour").length || 1)}ch` }}
            data-segment="hour"
          />
          <span
            className="-mx-0.5 text-[32px] leading-none font-light text-[var(--cdp-label)]"
            aria-hidden
          >
            :
          </span>
          <input
            ref={minuteRef}
            aria-label={labels.minute}
            inputMode="numeric"
            autoComplete="off"
            value={shownText("minute")}
            onChange={onInput("minute")}
            onBeforeInput={onBeforeInput("minute")}
            onKeyDown={onSegmentKeyDown("minute")}
            onFocus={(e) => e.currentTarget.select()}
            onBlur={() => setTyping(null)}
            className={segmentClass}
            style={{ width: "2ch" }}
            data-segment="minute"
          />
        </div>
        {twelve && (
          <SegmentedControl
            aria-label={labels.dayPeriod}
            options={[
              { value: false, label: periods.am },
              { value: true, label: periods.pm },
            ]}
            value={pm}
            onChange={setPm}
          />
        )}
      </div>

      {wheels && (
        <div className="cdp-wheel-mask relative flex justify-center" data-slot="time-wheels">
          <WheelHighlight />
          <Wheel
            aria-label={labels.hour}
            options={hourOptions}
            value={hourShown}
            loop
            onChange={setHour}
            className="w-16"
          />
          <Wheel
            aria-label={labels.minute}
            options={minuteOptions}
            value={minutes - (minutes % minuteInterval)}
            loop
            onChange={setMinute}
            className="w-16"
          />
          {twelve && (
            <Wheel
              aria-label={labels.dayPeriod}
              options={[
                { value: 0, label: periods.am },
                { value: 1, label: periods.pm },
              ]}
              value={pm ? 1 : 0}
              onChange={(v) => setPm(v === 1)}
              className="w-16"
            />
          )}
        </div>
      )}
    </div>
  );
}

import * as React from "react";

import { usePrefersReducedMotion } from "./hooks";
import { clamp, cn, mod } from "./utils";
import { easeOutCubic, flingTarget, nearestCopy, snapIndex } from "./wheel-math";

export type WheelOption = { value: number; label: string };

export type WheelProps = {
  options: WheelOption[];
  value: number;
  onChange: (value: number) => void;
  /** Hours and minutes wrap around like the iOS clock wheels. */
  loop?: boolean;
  itemHeight?: number;
  visibleRows?: number;
  "aria-label": string;
  className?: string;
};

// Looped wheels render the options this many times and rest in the middle
// copy, so a fling always has road in both directions.
const COPIES = 7;
const TYPEAHEAD_MS = 700;

type Drag = {
  startY: number;
  startTop: number;
  lastTop: number;
  lastT: number;
  v: number;
  moved: boolean;
};

/**
 * One column of an iOS picker: native scrolling with snap points (so touch
 * and trackpad flings come from the platform), mouse drag with its own
 * deceleration, a click on any row, and the keyboard — arrows step, digits
 * jump. The centre row is the value; the parent draws the highlight bar.
 */
export function Wheel({
  options,
  value,
  onChange,
  loop = false,
  itemHeight = 32,
  visibleRows = 5,
  "aria-label": ariaLabel,
  className,
}: WheelProps) {
  const scroller = React.useRef<HTMLDivElement>(null);
  const reduceMotion = usePrefersReducedMotion();
  const len = options.length;
  const copies = loop ? COPIES : 1;
  const base = loop ? Math.floor(COPIES / 2) * len : 0;
  const maxIndex = len * copies - 1;
  const selected = Math.max(
    0,
    options.findIndex((o) => o.value === value),
  );
  const pad = ((visibleRows - 1) / 2) * itemHeight;

  // Physical row the wheel rests on; the value is `options[resting % len]`.
  const resting = React.useRef(base + selected);
  const drag = React.useRef<Drag | null>(null);
  const fling = React.useRef(0);
  const settleTimer = React.useRef(0);
  const typeahead = React.useRef({ buffer: "", timer: 0 });
  // A mouse click is resolved on pointer-up (pointer capture would retarget
  // the click event); the click that follows is then ignored. WebKit labels a
  // touch-synthesised click "mouse" too, so the click itself cannot be trusted.
  const clickHandled = React.useRef(false);
  // Timers and animation frames call back after this render; give them the
  // latest handler rather than the one they closed over.
  const onChangeRef = React.useRef(onChange);
  const valueRef = React.useRef(value);
  React.useLayoutEffect(() => {
    onChangeRef.current = onChange;
    valueRef.current = value;
  });

  // Only a different row is a change: settling where the wheel already was
  // (including the first layout) must not write anything.
  const report = (physical: number) => {
    const option = optionAt(physical);
    if (option && option.value !== valueRef.current) onChangeRef.current(option.value);
  };

  const optionAt = (physical: number) => options.at(mod(physical, len));

  // Depth: rows tilt away from the centre, like the drum of a real picker.
  const paint = () => {
    const el = scroller.current;
    if (!el) return;
    const centre = el.scrollTop / itemHeight;
    const rows = el.firstElementChild?.children;
    if (!rows) return;
    const from = Math.max(0, Math.floor(centre) - visibleRows);
    const to = Math.min(rows.length - 1, Math.ceil(centre) + visibleRows);
    const nearest = snapIndex(el.scrollTop, itemHeight);
    for (let i = from; i <= to; i++) {
      const row = rows[i] as HTMLElement;
      const offset = i - centre;
      const angle = clamp(offset * 22, -85, 85);
      row.style.transform = `perspective(600px) rotateX(${-angle}deg)`;
      row.style.opacity = String(clamp(1 - Math.abs(offset) * 0.28, 0.12, 1));
      if (i === nearest) row.dataset.active = "";
      else delete row.dataset.active;
    }
  };

  const scrollToIndex = (physical: number, smooth: boolean) => {
    const el = scroller.current;
    if (!el) return;
    el.scrollTo({
      top: clamp(physical, 0, maxIndex) * itemHeight,
      behavior: smooth && !reduceMotion ? "smooth" : "auto",
    });
  };

  // Where the wheel stopped becomes the value; looped wheels quietly re-centre.
  const settle = () => {
    const el = scroller.current;
    if (!el || drag.current || fling.current) return;
    let idx = snapIndex(el.scrollTop, itemHeight);
    if (loop) {
      const centred = base + mod(idx, len);
      if (idx !== centred) {
        idx = centred;
        el.scrollTop = idx * itemHeight;
      }
    }
    resting.current = idx;
    report(idx);
  };

  const go = (physical: number, smooth = true) => {
    const target = clamp(physical, 0, maxIndex);
    resting.current = target;
    report(target);
    scrollToIndex(target, smooth);
  };

  // Initial rest, without animation.
  const mounted = React.useRef(false);
  React.useLayoutEffect(() => {
    if (mounted.current) return;
    mounted.current = true;
    scroller.current?.scrollTo({ top: resting.current * itemHeight });
    paint();
  });

  // The value changed from outside (typed into the field, or set by the app).
  React.useEffect(() => {
    if (drag.current || fling.current) return;
    if (options.at(mod(resting.current, len))?.value === value) return;
    const physical = loop ? nearestCopy(selected, resting.current, len, copies) : selected;
    resting.current = physical;
    scroller.current?.scrollTo({
      top: physical * itemHeight,
      behavior: reduceMotion ? "auto" : "smooth",
    });
  }, [value, options, len, loop, selected, copies, itemHeight, reduceMotion, resting, scroller]);

  const onScroll = () => {
    paint();
    // `scrollend` is the real signal; the timer covers engines without it.
    window.clearTimeout(settleTimer.current);
    settleTimer.current = window.setTimeout(settle, 120);
  };

  const onScrollEnd = () => {
    window.clearTimeout(settleTimer.current);
    settle();
  };

  // Mouse drag: the browser gives touch a fling for free, the mouse needs one.
  const onPointerDown = (e: React.PointerEvent<HTMLDivElement>) => {
    if (e.pointerType !== "mouse" || e.button !== 0) return;
    const el = e.currentTarget;
    cancelAnimationFrame(fling.current);
    fling.current = 0;
    el.setPointerCapture(e.pointerId);
    el.style.scrollSnapType = "none";
    drag.current = {
      startY: e.clientY,
      startTop: el.scrollTop,
      lastTop: el.scrollTop,
      lastT: e.timeStamp,
      v: 0,
      moved: false,
    };
  };

  const onPointerMove = (e: React.PointerEvent<HTMLDivElement>) => {
    const d = drag.current;
    if (!d) return;
    const el = e.currentTarget;
    const top = clamp(d.startTop - (e.clientY - d.startY), 0, maxIndex * itemHeight);
    const dt = Math.max(1, e.timeStamp - d.lastT);
    d.v = d.v * 0.5 + ((top - d.lastTop) / dt) * 0.5;
    d.lastTop = top;
    d.lastT = e.timeStamp;
    if (Math.abs(e.clientY - d.startY) > 3) d.moved = true;
    el.scrollTop = top;
  };

  const onPointerUp = (e: React.PointerEvent<HTMLDivElement>) => {
    const d = drag.current;
    if (!d) return;
    drag.current = null;
    const el = e.currentTarget;
    el.releasePointerCapture(e.pointerId);
    if (!d.moved) {
      // A click: the row under the pointer becomes the value.
      el.style.scrollSnapType = "";
      const y = e.clientY - el.getBoundingClientRect().top;
      go(Math.floor((el.scrollTop + y - pad) / itemHeight));
      clickHandled.current = true;
      return;
    }
    clickHandled.current = true;
    const target = flingTarget(
      el.scrollTop,
      e.timeStamp - d.lastT > 80 ? 0 : d.v,
      itemHeight,
      maxIndex,
    );
    const from = el.scrollTop;
    const to = target * itemHeight;
    const duration = reduceMotion ? 0 : clamp(Math.abs(to - from) * 1.2, 180, 720);
    const start = e.timeStamp;
    const step = (now: number) => {
      const t = duration === 0 ? 1 : Math.min(1, (now - start) / duration);
      el.scrollTop = from + (to - from) * easeOutCubic(t);
      if (t < 1) {
        fling.current = requestAnimationFrame(step);
      } else {
        fling.current = 0;
        el.style.scrollSnapType = "";
        settle();
      }
    };
    fling.current = requestAnimationFrame(step);
  };

  const onKeyDown = (e: React.KeyboardEvent<HTMLDivElement>) => {
    const r = resting.current;
    const first = loop ? base : 0;
    const last = loop ? base + len - 1 : len - 1;
    switch (e.key) {
      case "ArrowUp":
        go(r - 1);
        break;
      case "ArrowDown":
        go(r + 1);
        break;
      case "PageUp":
        go(r - 5);
        break;
      case "PageDown":
        go(r + 5);
        break;
      case "Home":
        go(first);
        break;
      case "End":
        go(last);
        break;
      default: {
        if (e.key.length !== 1 || e.metaKey || e.ctrlKey || e.altKey) return;
        const ta = typeahead.current;
        window.clearTimeout(ta.timer);
        ta.buffer += e.key.toLowerCase();
        ta.timer = window.setTimeout(() => (ta.buffer = ""), TYPEAHEAD_MS);
        const hit = options.findIndex(
          (o) => String(o.value) === ta.buffer || o.label.toLowerCase().startsWith(ta.buffer),
        );
        if (hit === -1) {
          ta.buffer = e.key.toLowerCase();
          const retry = options.findIndex(
            (o) => String(o.value) === ta.buffer || o.label.toLowerCase().startsWith(ta.buffer),
          );
          if (retry === -1) return;
          go(loop ? nearestCopy(retry, r, len, copies) : retry);
        } else {
          go(loop ? nearestCopy(hit, r, len, copies) : hit);
        }
        break;
      }
    }
    e.preventDefault();
  };

  const current = options.at(selected);

  return (
    <div
      ref={scroller}
      role="spinbutton"
      tabIndex={0}
      aria-label={ariaLabel}
      aria-valuenow={current?.value}
      aria-valuetext={current?.label}
      aria-valuemin={options.at(0)?.value}
      aria-valuemax={options.at(-1)?.value}
      data-slot="wheel"
      onScroll={onScroll}
      onScrollEnd={onScrollEnd}
      onPointerDown={onPointerDown}
      onPointerMove={onPointerMove}
      onPointerUp={onPointerUp}
      onPointerCancel={onPointerUp}
      onKeyDown={onKeyDown}
      className={cn(
        "cdp-wheel relative snap-y snap-mandatory overflow-y-scroll overscroll-contain rounded-lg outline-none select-none focus-visible:ring-2 focus-visible:ring-[var(--cdp-tint)]",
        className,
      )}
      style={{ height: visibleRows * itemHeight, scrollbarWidth: "none", touchAction: "pan-y" }}
    >
      <div aria-hidden style={{ paddingBlock: pad }}>
        {Array.from({ length: len * copies }, (_, i) => {
          const option = options.at(i % len);
          return (
            <div
              key={i}
              role="presentation"
              className="flex snap-center items-center justify-center text-[22px] leading-none text-[var(--cdp-secondary)] tabular-nums transition-colors data-active:text-[var(--cdp-label)]"
              style={{ height: itemHeight }}
              onClick={() => {
                if (clickHandled.current) {
                  clickHandled.current = false;
                  return;
                }
                go(i);
              }}
            >
              {option?.label}
            </div>
          );
        })}
      </div>
    </div>
  );
}

/** The translucent bar behind the centre row, shared by a group of wheels. */
export function WheelHighlight({
  itemHeight = 32,
  className,
}: {
  itemHeight?: number;
  className?: string;
}) {
  return (
    <div
      aria-hidden
      className={cn(
        "pointer-events-none absolute inset-x-0 top-1/2 -translate-y-1/2 rounded-lg bg-[var(--cdp-fill)]",
        className,
      )}
      style={{ height: itemHeight }}
    />
  );
}

import * as React from "react";

import { cn } from "./utils";

export type SegmentedOption<T> = { value: T; label: string };

/**
 * The iOS segmented control: a translucent track with a white thumb that
 * slides to the chosen segment. Underneath it is a native radio group, so
 * arrow keys, focus and form semantics come from the browser.
 */
export function SegmentedControl<T extends string | number | boolean>({
  options,
  value,
  onChange,
  "aria-label": ariaLabel,
  className,
}: {
  options: SegmentedOption<T>[];
  value: T;
  onChange: (value: T) => void;
  "aria-label": string;
  className?: string;
}) {
  const name = React.useId();
  const index = Math.max(
    0,
    options.findIndex((o) => o.value === value),
  );
  return (
    <div
      role="radiogroup"
      aria-label={ariaLabel}
      data-slot="segmented-control"
      className={cn(
        "relative inline-grid h-8 auto-cols-fr grid-flow-col rounded-[9px] bg-[var(--cdp-fill)] p-0.5",
        className,
      )}
    >
      <div
        aria-hidden
        className="pointer-events-none absolute inset-y-0.5 left-0.5 rounded-[7px] bg-[var(--cdp-thumb)] shadow-[0_3px_8px_rgba(0,0,0,0.12),0_3px_1px_rgba(0,0,0,0.04)] transition-transform duration-200 ease-[cubic-bezier(0.2,0,0,1)]"
        style={{
          width: `calc((100% - 4px) / ${options.length})`,
          transform: `translateX(${index * 100}%)`,
        }}
      />
      {options.map((option) => {
        const checked = option.value === value;
        return (
          <label
            key={String(option.value)}
            className={cn(
              "relative z-10 flex min-w-12 cursor-pointer items-center justify-center rounded-[7px] px-3 text-[13px] font-semibold transition-colors select-none has-focus-visible:ring-2 has-focus-visible:ring-[var(--cdp-tint)]",
              checked ? "text-[var(--cdp-label)]" : "text-[var(--cdp-label)]/80 active:opacity-60",
            )}
          >
            <input
              type="radio"
              name={name}
              checked={checked}
              onChange={() => onChange(option.value)}
              // Covers the label so the radio itself is the hit target.
              className="absolute inset-0 cursor-pointer appearance-none opacity-0"
            />
            {option.label}
          </label>
        );
      })}
    </div>
  );
}

import * as React from "react";

/** Controlled when `value` is given, otherwise owned here. */
export function useControlled<T>(
  value: T | undefined,
  defaultValue: T,
  onChange: ((next: T) => void) | undefined,
): [T, (next: T) => void] {
  const [inner, setInner] = React.useState(defaultValue);
  const current = value === undefined ? inner : value;
  const set = (next: T) => {
    if (value === undefined) setInner(next);
    onChange?.(next);
  };
  return [current, set];
}

export function usePrefersReducedMotion(): boolean {
  return React.useSyncExternalStore(
    (notify) => {
      const query = window.matchMedia("(prefers-reduced-motion: reduce)");
      query.addEventListener("change", notify);
      return () => query.removeEventListener("change", notify);
    },
    () => window.matchMedia("(prefers-reduced-motion: reduce)").matches,
    () => false,
  );
}

/**
 * Calendar arithmetic on local `Date`s, with no library. A picker only ever
 * needs the month grid, day-level comparisons, and "same clock, other day".
 */
export type YearMonth = { year: number; month: number };

export function startOfDay(date: Date): Date {
  return new Date(date.getFullYear(), date.getMonth(), date.getDate());
}

export function isSameDay(a: Date | null | undefined, b: Date | null | undefined): boolean {
  return (
    !!a &&
    !!b &&
    a.getFullYear() === b.getFullYear() &&
    a.getMonth() === b.getMonth() &&
    a.getDate() === b.getDate()
  );
}

export function daysInMonth(year: number, month: number): number {
  return new Date(year, month + 1, 0).getDate();
}

export function yearMonthOf(date: Date): YearMonth {
  return { year: date.getFullYear(), month: date.getMonth() };
}

/** Months between `a` and `b`; negative when `b` is earlier. */
export function monthDiff(a: YearMonth, b: YearMonth): number {
  return (b.year - a.year) * 12 + (b.month - a.month);
}

export function shiftMonth(ym: YearMonth, by: number): YearMonth {
  const total = ym.month + by;
  return { year: ym.year + Math.floor(total / 12), month: ((total % 12) + 12) % 12 };
}

/** The same clock on another calendar day; the day is clamped into the month. */
export function withDay(base: Date, year: number, month: number, day: number): Date {
  const next = new Date(base);
  next.setFullYear(year, month, Math.min(day, daysInMonth(year, month)));
  return next;
}

export function withTime(base: Date, hours: number, minutes: number): Date {
  const next = new Date(base);
  next.setHours(hours, minutes, 0, 0);
  return next;
}

export function addDays(date: Date, days: number): Date {
  const next = new Date(date);
  next.setDate(next.getDate() + days);
  return next;
}

export function addMonths(date: Date, months: number): Date {
  const ym = shiftMonth(yearMonthOf(date), months);
  return withDay(date, ym.year, ym.month, date.getDate());
}

/** Whether the whole day lies outside [min, max]. */
export function isDayDisabled(date: Date, min?: Date, max?: Date): boolean {
  const day = startOfDay(date).getTime();
  if (min && day < startOfDay(min).getTime()) return true;
  if (max && day > startOfDay(max).getTime()) return true;
  return false;
}

export type DayCell = { date: Date; inMonth: boolean };

/**
 * Rows of seven for one month, starting on `weekStart` (0 = Sunday). Only as
 * many rows as the month needs, like the iOS inline calendar.
 */
export function monthGrid(year: number, month: number, weekStart: number): DayCell[][] {
  const lead = (new Date(year, month, 1).getDay() - weekStart + 7) % 7;
  const rows = Math.ceil((lead + daysInMonth(year, month)) / 7);
  return Array.from({ length: rows }, (_row, r) =>
    Array.from({ length: 7 }, (_cell, c) => {
      const date = new Date(year, month, r * 7 + c - lead + 1);
      return { date, inMonth: date.getMonth() === month };
    }),
  );
}

/** First day of the week for a locale, 0 = Sunday … 6 = Saturday. */
export function weekStartFor(locale: string): number {
  const firstDay = readFirstDay(locale);
  if (firstDay !== undefined) return firstDay % 7;
  return /^(en-(US|CA|AU)|ja|ko|zh-(TW|HK)|he|pt-BR|es-(MX|US))\b/i.test(locale) ? 0 : 1;
}

/**
 * `Intl.Locale#getWeekInfo` (or the older `weekInfo` getter) where the engine
 * has it, read without assuming either exists in the type library.
 */
function readFirstDay(locale: string): number | undefined {
  let l: object;
  try {
    l = new Intl.Locale(locale);
  } catch {
    return undefined;
  }
  const info: unknown =
    "getWeekInfo" in l && typeof l.getWeekInfo === "function"
      ? l.getWeekInfo()
      : "weekInfo" in l
        ? l.weekInfo
        : undefined;
  return typeof info === "object" &&
    info !== null &&
    "firstDay" in info &&
    typeof info.firstDay === "number"
    ? info.firstDay
    : undefined;
}

/**
 * Clock helpers on top of `Intl`, so 12/24-hour, day-period labels, and month
 * and weekday names all follow the locale instead of a hard-coded table.
 */
export type HourCycle = "h12" | "h23";

export function hourCycleFor(locale: string): HourCycle {
  const cycle = new Intl.DateTimeFormat(locale, { hour: "numeric" }).resolvedOptions().hourCycle;
  return cycle === "h11" || cycle === "h12" ? "h12" : "h23";
}

export function to12(hour24: number): { hour: number; pm: boolean } {
  return { hour: hour24 % 12 === 0 ? 12 : hour24 % 12, pm: hour24 >= 12 };
}

export function to24(hour12: number, pm: boolean): number {
  return (hour12 % 12) + (pm ? 12 : 0);
}

export function dayPeriodLabels(locale: string): { am: string; pm: string } {
  const f = new Intl.DateTimeFormat(locale, { hour: "numeric", hourCycle: "h12" });
  const label = (hour: number) =>
    f.formatToParts(new Date(2000, 0, 1, hour)).find((p) => p.type === "dayPeriod")?.value ??
    (hour < 12 ? "AM" : "PM");
  return { am: label(1), pm: label(13) };
}

export function monthNames(locale: string, style: "long" | "short" = "long"): string[] {
  const f = new Intl.DateTimeFormat(locale, { month: style });
  return Array.from({ length: 12 }, (_, m) => f.format(new Date(2000, m, 1)));
}

/** Seven names starting on `weekStart` (0 = Sunday). */
export function weekdayNames(
  locale: string,
  weekStart: number,
  style: "narrow" | "short" = "narrow",
): string[] {
  const f = new Intl.DateTimeFormat(locale, { weekday: style });
  // 2023-01-01 is a Sunday.
  return Array.from({ length: 7 }, (_, i) =>
    f.format(new Date(2023, 0, 1 + ((weekStart + i) % 7))),
  );
}

/** The locale's medium date, as the iOS pill shows it: "Sep 5, 2026", "05.09.2026", "2026年9月5日". */
export function formatDay(date: Date, locale: string): string {
  return new Intl.DateTimeFormat(locale, { dateStyle: "medium" }).format(date);
}

/** "6:30 PM" on a 12-hour clock, "06:30" on a 24-hour one. */
export function formatClock(date: Date, locale: string, hourCycle: HourCycle): string {
  return new Intl.DateTimeFormat(locale, {
    hour: hourCycle === "h12" ? "numeric" : "2-digit",
    minute: "2-digit",
    hourCycle,
  }).format(date);
}

export function formatMonthYear(date: Date, locale: string): string {
  return new Intl.DateTimeFormat(locale, { month: "long", year: "numeric" }).format(date);
}

export function formatFullDate(date: Date, locale: string): string {
  return new Intl.DateTimeFormat(locale, {
    weekday: "long",
    year: "numeric",
    month: "long",
    day: "numeric",
  }).format(date);
}

/**
 * Typing into a two-digit clock segment. The person types digits; the segment
 * shows what has been typed, commits as soon as the digits name a value, and
 * says when it is done so focus can move on (the second digit arrived, or no
 * further digit could still fit under `max`).
 */
export type DigitStep = { buffer: string; value: number | null; done: boolean };

export function typeDigit(buffer: string, digit: string, min: number, max: number): DigitStep {
  const next = buffer.length >= 2 ? digit : buffer + digit;
  const n = Number(next);
  if (n > max) {
    // The pair cannot be a value: start over with just this digit.
    const d = Number(digit);
    return d > max || d < min
      ? { buffer: "", value: null, done: false }
      : { buffer: digit, value: d, done: d * 10 > max };
  }
  return { buffer: next, value: n >= min ? n : null, done: next.length === 2 || n * 10 > max };
}

/** Step within [min, max], wrapping at both ends. */
export function stepValue(value: number, by: number, min: number, max: number): number {
  const span = max - min + 1;
  return min + ((((value - min + by) % span) + span) % span);
}

import { clamp } from "./utils";

/** The row a scroll offset rests on. */
export function snapIndex(scrollTop: number, itemHeight: number): number {
  return Math.round(scrollTop / itemHeight);
}

/**
 * Where a released drag comes to rest. `velocity` is d(scrollTop)/dt in
 * px/ms; the projection mirrors UIScrollView's normal deceleration, then
 * lands on a row.
 */
export function flingTarget(
  scrollTop: number,
  velocity: number,
  itemHeight: number,
  maxIndex: number,
): number {
  const projected = scrollTop + velocity * 380;
  return clamp(snapIndex(projected, itemHeight), 0, maxIndex);
}

/** Of the copies of `logical` in a looped wheel, the one nearest `from`. */
export function nearestCopy(logical: number, from: number, len: number, copies: number): number {
  let best = logical;
  for (let c = 0; c < copies; c++) {
    const candidate = c * len + logical;
    if (Math.abs(candidate - from) < Math.abs(best - from)) best = candidate;
  }
  return best;
}

export function easeOutCubic(t: number): number {
  return 1 - (1 - t) ** 3;
}

import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

export function clamp(n: number, min: number, max: number) {
  return Math.min(max, Math.max(min, n));
}

/** Wrap `n` into [0, len). */
export function mod(n: number, len: number) {
  return ((n % len) + len) % len;
}

export function pad2(n: number) {
  return n < 10 ? `0${n}` : String(n);
}

/*
 * Tokens follow the iOS system palette: tint, the translucent fills, and
 * the label hierarchy. Override `--cdp-tint` to re-tint; add `.dark` (or
 * `data-theme="dark"`) on an ancestor for dark mode.
 */
:root {
  --cdp-tint: #007aff;
  --cdp-tint-fill: color-mix(in srgb, var(--cdp-tint) 14%, transparent);
  --cdp-on-tint: #fff;
  --cdp-fill: rgba(120, 120, 128, 0.12);
  --cdp-fill-hover: rgba(120, 120, 128, 0.2);
  --cdp-label: #000;
  --cdp-secondary: rgba(60, 60, 67, 0.6);
  --cdp-tertiary: rgba(60, 60, 67, 0.3);
  --cdp-bg: #fff;
  --cdp-thumb: #fff;
  --cdp-shadow:
    0 0 0 0.5px rgba(0, 0, 0, 0.06), 0 4px 12px rgba(0, 0, 0, 0.06), 0 16px 48px rgba(0, 0, 0, 0.18);
}

.dark,
[data-theme="dark"] {
  --cdp-tint: #0a84ff;
  --cdp-fill: rgba(120, 120, 128, 0.24);
  --cdp-fill-hover: rgba(120, 120, 128, 0.32);
  --cdp-label: #fff;
  --cdp-secondary: rgba(235, 235, 245, 0.6);
  --cdp-tertiary: rgba(235, 235, 245, 0.3);
  --cdp-bg: #1c1c1e;
  --cdp-thumb: #636366;
  --cdp-shadow:
    0 0 0 0.5px rgba(255, 255, 255, 0.12), 0 4px 12px rgba(0, 0, 0, 0.3),
    0 16px 48px rgba(0, 0, 0, 0.6);
}

.cdp {
  font-family:
    -apple-system, BlinkMacSystemFont, "SF Pro Text", "SF Pro Display", "Helvetica Neue", system-ui,
    sans-serif;
  -webkit-font-smoothing: antialiased;
  -webkit-tap-highlight-color: transparent;
  color: var(--cdp-label);
}

.cdp-wheel::-webkit-scrollbar {
  display: none;
}

.cdp-wheel-mask {
  mask-image: linear-gradient(to bottom, transparent, black 22%, black 78%, transparent);
}

@keyframes cdp-pop-in {
  from {
    opacity: 0;
    transform: scale(0.86);
  }
  to {
    opacity: 1;
    transform: scale(1);
  }
}

@keyframes cdp-pop-out {
  to {
    opacity: 0;
    transform: scale(0.96);
  }
}

@keyframes cdp-slide-from-right {
  from {
    opacity: 0;
    transform: translateX(28px);
  }
}

@keyframes cdp-slide-from-left {
  from {
    opacity: 0;
    transform: translateX(-28px);
  }
}

@media (prefers-reduced-motion: reduce) {
  .cdp *,
  .cdp {
    animation-duration: 0.01ms !important;
    transition-duration: 0.01ms !important;
  }
}
